const input = $input.first();
const json = (input && input.json) || {};

let triggerSource = 'mattermost';
try {
  if ($('Webhook Trigger (sm-standup)').first()) {
    triggerSource = 'webhook';
  }
} catch (e) {
  triggerSource = 'mattermost';
}

// ── Xử lý lỗi khi không kết nối được Jira API ───────────────────────────────
if (json.error || json.errorMessages || (json.message && !json.issues)) {
  const errMsg = (json.errorMessages && json.errorMessages.join(', ')) || 
                 (json.error && (json.error.message || json.error.description)) || 
                 json.message || 'Không thể kết nối đến Jira Search API';
  const reportText = `🚨 **[Lỗi Báo Cáo Daily Standup]** Không thể lấy danh sách Sprint đang mở:\n> ${errMsg}\n\n*Gợi ý: Kiểm tra cấu hình ATLASSIAN_BASE_URL, ATLASSIAN_EMAIL và API Token trong file .env.*`;

  return [{
    json: {
      isError: true,
      error: errMsg,
      reportText: reportText,
      totalIssues: 0,
      stuckCount: 0,
      _triggerSource: triggerSource
    }
  }];
}

// ── Phân tích dữ liệu Sprint ────────────────────────────────────────────────
const issues = json.issues || [];
const now = new Date();
const stuckIssues = [];
const assigneeWorkload = {};

for (const issue of issues) {
  const f = issue.fields;
  const assignee = f.assignee ? f.assignee.displayName : 'Chưa phân bổ';
  assigneeWorkload[assignee] = (assigneeWorkload[assignee] || 0) + 1;

  // Kiểm tra ticket bị kẹt > 3 ngày chưa cập nhật
  const updated = new Date(f.updated);
  const diffDays = (now - updated) / (1000 * 60 * 60 * 24);
  if (diffDays >= 3) {
    stuckIssues.push({
      key: issue.key,
      summary: f.summary,
      assignee: assignee,
      status: f.status ? f.status.name : '',
      stuckDays: Math.round(diffDays)
    });
  }
}

let reportText = `### 📋 BÁO CÁO DAILY STANDUP (${now.toISOString().split('T')[0]})\n`;
reportText += `- **Tổng số task đang mở:** ${issues.length}\n`;
reportText += `- **Cảnh báo Task bị treo (>3 ngày):** ${stuckIssues.length}\n\n`;

if (stuckIssues.length > 0) {
  reportText += `#### 🚨 Danh sách Task bị tắc nghẽn (Impediments):\n`;
  for (const s of stuckIssues) {
    reportText += `- **[${s.key}]** ${s.summary} (👤 ${s.assignee} | ⏳ ${s.stuckDays} ngày chưa cập nhật)\n`;
  }
}

return [{
  json: {
    isError: false,
    reportText: reportText,
    totalIssues: issues.length,
    stuckCount: stuckIssues.length,
    _triggerSource: triggerSource
  }
}];
